deepml specialized 0.3
module corpus.deepml_specialized.example_02001
policy deterministic
policy no_network
domain finance {
  unit InputUnit = base("input")
  tensor x: f64<InputUnit>[13,12]
  operator project_radiance(x) -> Tensor pure deterministic
  calibration C02001 { method: bounded_least_squares tolerance: 1e-6 }
  constraint PhysicalBounds { min: 0 max: 301 }
  validate x with [project_radiance, C02001, PhysicalBounds]
}

